from copy import deepcopy


def latest_job_states(configured_ids, events):
    if not isinstance(configured_ids, (list, tuple)):
        raise TypeError("configured_ids must be a list or tuple")
    if not isinstance(events, (list, tuple)):
        raise TypeError("events must be a list or tuple")

    configured = set()
    for job_id in configured_ids:
        if not isinstance(job_id, str):
            raise TypeError("job identifiers must be strings")
        if not job_id:
            raise ValueError("job identifiers may not be empty")
        if job_id in configured:
            raise ValueError("configured identifiers must be unique")
        configured.add(job_id)

    latest = {}
    for event in events:
        if not isinstance(event, dict):
            raise TypeError("events must be dictionaries")
        if "job_id" not in event or "state" not in event:
            raise ValueError("event is missing a required field")
        job_id, state = event["job_id"], event["state"]
        if not isinstance(job_id, str) or not isinstance(state, str):
            raise TypeError("event identifiers and states must be strings")
        if not job_id or not state:
            raise ValueError("event identifiers and states may not be empty")
        if job_id in configured:
            latest.setdefault(job_id, deepcopy(event))

    return [deepcopy(latest.get(job_id, {"job_id": job_id, "state": "missing"})) for job_id in configured_ids]
```

